package dev.kelmagic.worldgen;
import java.util.*;import java.util.concurrent.CompletableFuture;import java.time.Duration;import com.mojang.datafixers.util.Pair;import dev.kelmagic.KelMagic;import dev.kelmagic.mixin.ArchiveChunkAccess;import net.minecraft.commands.CommandSourceStack;import net.minecraft.commands.arguments.ResourceOrTagKeyArgument;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.network.chat.Component;import net.minecraft.server.commands.LocateCommand;import net.minecraft.server.level.*;import net.minecraft.world.level.ChunkPos;import net.minecraft.world.level.chunk.*;import net.minecraft.world.level.chunk.status.ChunkStatus;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.placement.RandomSpreadStructurePlacement;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
/** Server-thread state machine: no join/get/managedBlock and no world access on a worker thread. */
@EventBusSubscriber(modid=KelMagic.MODID)public final class ArchiveSearch {
 private static final Map<String,Job> JOBS=new LinkedHashMap<>();
 private static final TicketType<String> TICKET=TicketType.create("kelmagic_archive_search",Comparator.<String>naturalOrder());
 private record CacheKey(ServerLevel level,long chunk,Set<Structure> villages){} private record Cached(List<BlockPos> positions,long until){}
 private static final Map<CacheKey,Cached> CACHE=new LinkedHashMap<>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<CacheKey,Cached> e){return size()>2048;}};
 public static boolean accepts(CommandSourceStack s,ResourceOrTagKeyArgument.Result<Structure> arg){var r=s.getLevel().registryAccess().registryOrThrow(Registries.STRUCTURE);return arg.unwrap().map(k->k.equals(ArchiveWorldgen.ARCHIVE),t->r.getTag(t).map(set->set.size()>0&&set.stream().allMatch(ArchiveLocator::isArchive)).orElse(false));}
 private static String owner(CommandSourceStack s){return s.getEntity()!=null?s.getEntity().getUUID().toString():s.getTextName()+"@"+s.getLevel().dimension().location();}
 public static int cancel(CommandSourceStack s){var job=JOBS.remove(owner(s));if(job==null)return 0;job.close();s.sendSuccess(()->Component.translatable("commands.kelmagic.search_cancelled"),false);return 1;}
 public static int begin(CommandSourceStack s,ResourceOrTagKeyArgument.Result<Structure> arg){if(!s.hasPermission(2))return 0;String key=owner(s);var old=JOBS.remove(key);if(old!=null)old.close();if(JOBS.size()>=2){s.sendFailure(Component.translatable("commands.kelmagic.search_busy"));return 0;}JOBS.put(key,new Job(s,arg));s.sendSuccess(()->Component.translatable("commands.kelmagic.search_started"),false);return 1;}
 public static int pending(){return JOBS.size();}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){long budget=System.nanoTime()+2_000_000;for(var it=JOBS.values().iterator();it.hasNext()&&System.nanoTime()<budget;){var job=it.next();if(job.source.getServer()!=e.getServer())continue;try{if(job.step()){job.close();it.remove();}}catch(Exception ex){job.close();it.remove();job.source.sendFailure(Component.translatable("commands.kelmagic.search_failed"));KelMagic.LOGGER.warn("Archive search failed",ex);}}}
 @SubscribeEvent public static void stop(net.neoforged.neoforge.event.server.ServerStoppingEvent e){for(var j:JOBS.values())j.close();JOBS.clear();CACHE.clear();}
 @SubscribeEvent public static void reload(net.neoforged.neoforge.event.OnDatapackSyncEvent e){CACHE.clear();}
 private record Candidate(RandomSpreadStructurePlacement placement,Set<Structure> villages,ChunkPos chunk){}
 private static final class Job {
  final CommandSourceStack source;final ResourceOrTagKeyArgument.Result<Structure> argument;final ServerLevel level;final BlockPos origin;final ChunkPos center;final long started=System.nanoTime();final List<Map.Entry<RandomSpreadStructurePlacement,Set<Structure>>> placements;final Set<Candidate> seen=new HashSet<>();final ArrayDeque<Candidate> queue=new ArrayDeque<>();
  final String ticketId=UUID.randomUUID().toString();int ring,examined;BlockPos best;double distance=Double.MAX_VALUE;Candidate active;CompletableFuture<ChunkResult<ChunkAccess>> future;
  Job(CommandSourceStack s,ResourceOrTagKeyArgument.Result<Structure> a){source=s;argument=a;level=s.getLevel();origin=BlockPos.containing(s.getPosition());center=new ChunkPos(origin);placements=new ArrayList<>(ArchiveLocator.placements(level).entrySet());fillRing();}
  void fillRing(){var state=level.getChunkSource().getGeneratorState();for(var entry:placements){var p=entry.getKey();for(int x=-ring;x<=ring;x++)for(int z=-ring;z<=ring;z++){if(Math.abs(x)!=ring&&Math.abs(z)!=ring)continue;var chunk=p.getPotentialStructureChunk(state.getLevelSeed(),center.x+x*p.spacing(),center.z+z*p.spacing());var c=new Candidate(p,entry.getValue(),chunk);if(seen.add(c)&&p.isStructureChunk(state,chunk.x,chunk.z))queue.add(c);}}}
  boolean step(){if(source.getEntity() instanceof ServerPlayer p&&(p.isRemoved()||p.serverLevel()!=level))return true;if(System.nanoTime()-started>120_000_000_000L){source.sendFailure(Component.translatable("commands.kelmagic.search_timeout"));return true;}
   if(future!=null){if(!future.isDone())return false;var value=future.getNow(null);if(value!=null&&!future.isCompletedExceptionally()){var chunk=value.orElse(null);if(chunk!=null){var positions=new ArrayList<BlockPos>();for(var village:active.villages){var start=chunk.getStartForStructure(village);if(start!=null)positions.addAll(ArchiveLocator.positions(start));}CACHE.put(new CacheKey(level,active.chunk.toLong(),active.villages),new Cached(List.copyOf(positions),System.nanoTime()+300_000_000_000L));consider(positions);}}release();examined++;return false;}
   if(queue.isEmpty()){if(best!=null){var holder=level.registryAccess().registryOrThrow(Registries.STRUCTURE).getHolder(ArchiveWorldgen.ARCHIVE).orElseThrow();LocateCommand.showLocateResult(source,argument,origin,Pair.of(best,holder),"commands.locate.structure.success",false,Duration.ofNanos(System.nanoTime()-started));if(source.getEntity() instanceof ServerPlayer p)dev.kelmagic.server.MagicProgress.award(p,"archive_route");return true;}if(++ring>100||placements.isEmpty()){source.sendFailure(Component.translatable("commands.locate.structure.not_found",argument.asPrintable()));return true;}fillRing();return false;}
   active=queue.removeFirst();var cached=CACHE.get(new CacheKey(level,active.chunk.toLong(),active.villages));if(cached!=null&&cached.until>System.nanoTime()){consider(cached.positions);active=null;examined++;return false;}
   var access=(ArchiveChunkAccess)(Object)level.getChunkSource();boolean generate=level.getServer().getWorldData().worldGenOptions().generateStructures();if(generate)access.kelmagic$tickets().addTicket(TICKET,active.chunk,ChunkLevel.byStatus(ChunkStatus.STRUCTURE_STARTS),ticketId);
   future=access.kelmagic$request(active.chunk.x,active.chunk.z,ChunkStatus.STRUCTURE_STARTS,generate);return false;
  }
  void consider(List<BlockPos> list){for(var at:list){double x=(double)at.getX()-origin.getX(),z=(double)at.getZ()-origin.getZ(),d=x*x+z*z;if(d<distance){best=at;distance=d;}}}
  void release(){if(active!=null)((ArchiveChunkAccess)(Object)level.getChunkSource()).kelmagic$tickets().removeTicket(TICKET,active.chunk,ChunkLevel.byStatus(ChunkStatus.STRUCTURE_STARTS),ticketId);future=null;active=null;}
  void close(){release();}
 }
 private ArchiveSearch(){}
}
